xml.Script:
        clYellow       := 'FFFF00';
        clBlue         := '0000A0';
        clViolett      := '800080';
        clRed          := 'FF0000';
        clGreen        := '008000';
        clOrange       := 'FF6000';
        clLightBlue    := '2828FF';
        clLightViolett := 'FF0080';
        clBrown        := '800000';
        clLightGreen   := '00FF00';

        R := 0.5;
        H := R * 1.0;

        for i := 0 to 4 do begin
            x[i] := R * cos(2*Pi/5*i);
            y[i] := R * sin(2*Pi/5*i);

            ax[i] :=-cos(2*Pi/5*i);
            ay[i] :=-sin(2*Pi/5*i);
        end;

        az := sin(Pi/5);
        D := H * az / sqrt(1 + az^2);

        A1 := ArcCos((sqrt(5) - 5) / 8);
        A2 := ArcCos(-(1 + 5 * sqrt(5)) / 16);
